// Checkout conversion module - forces paid event on successful offer acceptance
const axios = require('axios');

module.exports = async function processCheckout(userId, offerId, amount) {
  try {
    // Simulate offer acceptance logic
    const accepted = Math.random() > 0.3; // 70% acceptance rate for testing
    if (!accepted) {
      console.log(`Offer ${offerId} not accepted by user ${userId}`);
      return { success: false, reason: 'not_accepted' };
    }

    // Record paid event
    const payload = {
      event: 'paid',
      userId,
      offerId,
      amount,
      timestamp: new Date().toISOString()
    };

    // Post to revenue endpoint
    const resp = await axios.post('http://localhost:4000/api/revenue/event', payload, {
      timeout: 5000
    });

    console.log(`Paid event recorded: ${resp.status}`);
    return { success: true, eventId: resp.data.eventId };
  } catch (err) {
    console.error('Checkout conversion error:', err.message);
    return { success: false, reason: err.message };
  }
};
